/** The project row a clone is written as; the service decides every value. */
export interface CloneProjectDraft {
  readonly orgId: OrgId;
  readonly name: string;
  readonly slug: string;
  readonly key: string;
  readonly description: string | null;
  readonly visibility: ProjectVisibility;
  readonly leadId: UserId | null;
  readonly color: string;
}

/** One issue written into a clone; numbering and resets are the service's call. */
export interface CloneIssueDraft {
  readonly number: number;
  readonly title: string;
  readonly description: string | null;
  readonly status: IssueStatus;
  readonly priority: IssuePriority;
  readonly authorId: UserId;
  readonly assigneeId: UserId | null;
  readonly parentId: IssueId | null;
  readonly estimate: number | null;
  readonly dueAt: IsoTimestamp | null;
  readonly startedAt: IsoTimestamp | null;
  readonly completedAt: IsoTimestamp | null;
  readonly labelIds: readonly LabelId[];
}

/**
 * Writes a clone and all of its issues in one transaction, so a failure part
 * way leaves neither a project nor a partial batch behind. The slug is made
 * unique against the org's slugs inside the transaction, as `insertProject`
 * does, and the copied issues and their labels are written alongside.
 */
export async function insertClone(
  draft: CloneProjectDraft,
  copies: readonly CloneIssueDraft[],
): Promise<Project> {
  return getDb().transaction((tx) => {
    const taken = tx
      .select({ slug: projects.slug })
      .from(projects)
      .where(orgPredicate(projects.orgId, draft.orgId))
      .all()
      .map((row) => row.slug);

    const stamp = toIsoTimestamp(new Date());
    const row = tx
      .insert(projects)
      .values({
        id: newId(),
        orgId: draft.orgId,
        name: draft.name,
        slug: uniqueSlug(draft.slug, taken),
        key: draft.key,
        description: draft.description,
        visibility: draft.visibility,
        status: "active",
        leadId: draft.leadId,
        color: draft.color,
        startsAt: null,
        targetDate: null,
        createdAt: stamp,
        updatedAt: stamp,
      })
      .returning()
      .get();

    for (const copy of copies) {
      const issueId = newId();
      tx.insert(issues)
        .values({
          id: issueId,
          orgId: draft.orgId,
          projectId: row.id,
          number: copy.number,
          title: copy.title,
          description: copy.description,
          status: copy.status,
          priority: copy.priority,
          authorId: copy.authorId,
          assigneeId: copy.assigneeId,
          parentId: copy.parentId,
          estimate: copy.estimate,
          dueAt: copy.dueAt,
          startedAt: copy.startedAt,
          completedAt: copy.completedAt,
          createdAt: stamp,
          updatedAt: stamp,
        })
        .run();

      if (copy.labelIds.length > 0) {
        tx.insert(issueLabels)
          .values(
            copy.labelIds.map((labelId) => ({
              orgId: draft.orgId,
              issueId,
              labelId,
            })),
          )
          .run();
      }
    }

    return toProject(row);
  });
}

/** Includes archived slugs — a restored project must not collide. */

