/**
 * Copies a live project into a new project of the same workspace. The clone
 * takes the source's description, visibility, lead and colour, starts active
 * and unarchived, and gets the name, slug and key the caller chose. With
 * `includeIssues`, every live issue is copied as a fresh start: default status,
 * unassigned, no progress timestamps, authored by the caller, numbered from 1
 * in the source's order. Comments, attachments and links are never copied.
 *
 * Gated like a creation (read on the source, `project:create` on the org, the
 * plan's project quota) plus the plan's per-project issue quota over the whole
 * batch. Everything is checked before anything is written, and the write is a
 * single transaction. Publishes one `project.cloned`, not `project.created` or
 * one `issue.created` per copy.
 */
export async function cloneProject(
  actor: Actor,
  input: CloneProjectInput,
): Promise<Project> {
  assertOrgScope(actor, input.orgId);

  const source = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertCan(actor, "project:read", projectResource(source));
  assertNotArchived("Project", source.id, source);
  assertCan(actor, "project:create", orgResource(input.orgId));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  const projectsUsed = await projectRepo.countProjects(input.orgId);
  if (wouldExceedLimit(org.plan, "projects", projectsUsed)) {
    throw new Error(
      `Plan ${org.plan} allows ${projectsUsed} projects; upgrade to add another`,
    );
  }

  const sourceIssues = input.includeIssues
    ? await issueRepo.listAllLiveIssues(input.orgId, source.id)
    : [];
  if (
    wouldExceedLimit(org.plan, "issuesPerProject", 0, sourceIssues.length)
  ) {
    throw new Error(
      `Plan ${org.plan} allows no more than ${getLimit(org.plan, "issuesPerProject")} issues in a project; this clone would copy ${sourceIssues.length}`,
    );
  }

  const copies = sourceIssues.map((issue, index) => ({
    number: index + 1,
    title: issue.title,
    description: issue.description,
    status: CLONED_ISSUE_STATUS,
    priority: issue.priority,
    authorId: actor.userId,
    assigneeId: null,
    parentId: null,
    estimate: issue.estimate,
    dueAt: issue.dueAt,
    startedAt: null,
    completedAt: null,
    labelIds: issue.labelIds,
  }));

  const clone = await projectRepo.insertClone(
    {
      orgId: input.orgId,
      name: input.name,
      slug: input.slug,
      key: input.key,
      description: source.description,
      visibility: source.visibility,
      leadId: source.leadId,
      color: source.color,
    },
    copies,
  );

  await emit("project.cloned", {
    ...actorEnvelope(actor),
    projectId: clone.id,
    sourceProjectId: source.id,
    issuesCopied: copies.length,
  });

  return clone;
}

