import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import { subscribe } from "@/lib/event-bus";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import * as searchService from "@/server/services/search-service";
import * as activityService from "@/server/services/activity-service";
import * as usageService from "@/server/services/usage-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { OrgId } from "@/types/common";

let cleanup: () => void;
const detach: Array<() => void> = [];

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detach.push(searchService.registerSearchListeners());
  detach.push(activityService.registerActivityListeners());
  detach.push(usageService.registerUsageListeners());
});

afterAll(() => {
  for (const off of detach) off();
  cleanup();
});

describe("scratch: cloneProject", () => {
  it("copies live issues with resets, labels, numbering; skips comments and archived", async () => {
    const tenant = await createTenant("scratchclone1", "growth");
    const m = tenant.actors.member;
    const label = await labelRepo.insertLabel({ orgId: tenant.org.id, name: "bug", color: "#ff0000", description: null } as never);

    const a = await issueService.createIssue(m, issueInput(tenant.org.id, tenant.project.id, { title: "Alpha item", assigneeId: tenant.userIds.admin }));
    const b = await issueService.createIssue(m, issueInput(tenant.org.id, tenant.project.id, { title: "Bravo item" }));
    const c = await issueService.createIssue(m, issueInput(tenant.org.id, tenant.project.id, { title: "Charlie archived" }));
    await labelRepo.setIssueLabels(tenant.org.id, a.id, [label.id]);
    await issueService.changeIssueStatus(m, { orgId: tenant.org.id, issueId: a.id, status: "done" });
    await commentService.createComment(m, { orgId: tenant.org.id, issueId: a.id, body: "a comment", parentId: null, mentionedUserIds: [] });
    await issueService.archiveIssue(m, tenant.org.id, c.id);
    await issueService.changeIssueStatus(m, { orgId: tenant.org.id, issueId: b.id, status: "in_progress" });

    const events: unknown[] = [];
    const seenCreated: unknown[] = [];
    const offA = subscribe("project.cloned", (p) => { events.push(p); });
    const offB = subscribe("project.created", (p) => { seenCreated.push(p); });
    const offC = subscribe("issue.created", (p) => { seenCreated.push(p); });

    const clone = await projectService.cloneProject(m, {
      orgId: tenant.org.id, projectId: tenant.project.id, name: "Scratch Clone", slug: "platform", key: "SCL", includeIssues: true,
    });
    offA(); offB(); offC();

    expect(clone.id).not.toBe(tenant.project.id);
    expect(clone.slug).toBe("platform-2");
    expect(clone.key).toBe("SCL");
    expect(clone.status).toBe("active");
    expect(clone.archivedAt).toBeNull();
    expect(clone.leadId).toBe(tenant.project.leadId);
    expect(clone.color).toBe(tenant.project.color);
    expect(clone.targetDate).toBeNull();

    const copies = await issueRepo.listAllLiveIssues(tenant.org.id, clone.id);
    expect(copies.map((i) => [i.number, i.title, i.status, i.assigneeId, i.authorId, i.startedAt, i.completedAt, i.labelIds.length, i.parentId])).toEqual([
      [1, "Alpha item", "backlog", null, m.userId, null, null, 1, null],
      [2, "Bravo item", "backlog", null, m.userId, null, null, 0, null],
    ]);

    expect(events).toEqual([expect.objectContaining({ projectId: clone.id, sourceProjectId: tenant.project.id, issuesCopied: 2, actorId: m.userId })]);
    expect(seenCreated).toHaveLength(0);

    // source untouched
    const sourceIssues = await issueRepo.listAllLiveIssues(tenant.org.id, tenant.project.id);
    expect(sourceIssues.map((i) => [i.title, i.status])).toEqual([["Alpha item", "done"], ["Bravo item", "in_progress"]]);
    expect(await issueRepo.countIssues(tenant.org.id, tenant.project.id, { includeArchived: true })).toBe(3);

    // audit row
    const audit = await activityRepo.listActivity({ orgId: tenant.org.id, action: ["project.cloned"], limit: 10, cursor: null, projectId: clone.id } as never);
    expect(audit.items).toHaveLength(1);
    expect(audit.items[0]).toMatchObject({ action: "project.cloned", subjectKind: "project", subjectId: clone.id, projectId: clone.id, metadata: { sourceProjectId: tenant.project.id, issuesCopied: 2 } });

    // search index
    const hits = await searchService.search(m, { orgId: tenant.org.id, q: "Alpha", kinds: ["issue"], limit: 25, cursor: null } as never);
    expect(hits.items.map((h) => h.id).length).toBeGreaterThanOrEqual(2);
    const projHits = await searchService.search(m, { orgId: tenant.org.id, q: "Scratch Clone", kinds: ["project"], limit: 25, cursor: null } as never);
    expect(projHits.items.map((h) => h.id)).toContain(clone.id);

    // usage
    const usage = await usageRepo.getUsage(tenant.org.id);
    expect(usage.projectsUsed).toBeGreaterThanOrEqual(2);
  });

  it("includeIssues=false copies no issues", async () => {
    const tenant = await createTenant("scratchclone2", "growth");
    await issueService.createIssue(tenant.actors.member, issueInput(tenant.org.id, tenant.project.id, { title: "Only one" }));
    const clone = await projectService.cloneProject(tenant.actors.member, {
      orgId: tenant.org.id, projectId: tenant.project.id, name: "Empty Copy", slug: "empty-copy", key: "EMP", includeIssues: false,
    });
    expect(await issueRepo.listAllLiveIssues(tenant.org.id, clone.id)).toHaveLength(0);
  });

  it("refuses a viewer and refuses a missing key without leaving anything behind", async () => {
    const tenant = await createTenant("scratchclone3", "growth");
    await issueService.createIssue(tenant.actors.member, issueInput(tenant.org.id, tenant.project.id, { title: "Keep me" }));
    await expect(projectService.cloneProject(tenant.actors.viewer, {
      orgId: tenant.org.id, projectId: tenant.project.id, name: "Nope", slug: "nope", key: "NOP", includeIssues: true,
    })).rejects.toThrow();
    // key "PLAT" collides with the source's key
    await expect(projectService.cloneProject(tenant.actors.member, {
      orgId: tenant.org.id, projectId: tenant.project.id, name: "Dup key", slug: "dup-key", key: "PLAT", includeIssues: true,
    })).rejects.toThrow();
    const page = await projectRepo.listProjects({ orgId: tenant.org.id, limit: 100, cursor: null });
    expect(page.items.map((p) => p.slug)).toEqual(["platform"]);
    expect(await issueRepo.countIssues(tenant.org.id, tenant.project.id)).toBe(1);
  });

  it("applies the project quota", async () => {
    const tenant = await createTenant("scratchclone4", "free");
    await projectService.cloneProject(tenant.actors.member, {
      orgId: tenant.org.id, projectId: tenant.project.id, name: "First Clone", slug: "first-clone", key: "FC", includeIssues: true,
    });
    await expect(projectService.cloneProject(tenant.actors.member, {
      orgId: tenant.org.id, projectId: tenant.project.id, name: "Second Clone", slug: "second-clone", key: "SC", includeIssues: true,
    })).rejects.toThrow(/allows 2 projects/);
  });

  it("refuses the whole batch when the issue quota does not fit, creating nothing", async () => {
    const tenant = await createTenant("scratchclone5", "free");
    // Bypass the service quota to put 101 live issues (free allows 100) in the source.
    for (let i = 0; i < 101; i += 1) {
      await issueRepo.insertIssue(
        { ...issueInput(tenant.org.id, tenant.project.id, { title: `Bulk ${i}` }) } as never,
        tenant.userIds.member,
        i + 1,
      );
    }
    const before = await projectRepo.listProjects({ orgId: tenant.org.id, limit: 100, cursor: null });
    await expect(projectService.cloneProject(tenant.actors.member, {
      orgId: tenant.org.id, projectId: tenant.project.id, name: "Too Big", slug: "too-big", key: "TB", includeIssues: true,
    })).rejects.toThrow(/allows 100 issues per project; this clone would copy 101/);
    const after = await projectRepo.listProjects({ orgId: tenant.org.id, limit: 100, cursor: null });
    expect(after.total).toBe(before.total);
    // without issues the same project clones fine
    const ok = await projectService.cloneProject(tenant.actors.member, {
      orgId: tenant.org.id, projectId: tenant.project.id, name: "No Issues", slug: "no-issues", key: "NI", includeIssues: false,
    });
    expect(ok.id).toBeTruthy();
    void (null as unknown as OrgId);
  });
});

