      orgId: tenant.org.id, projectId: tenant.project.id, name: "Second Clone", slug: "second-clone", key: "SC", includeIssues: true,
    })).rejects.toThrow(/allows 2 projects/);
  });

  it("refuses the whole batch when the issue quota does not fit, creating nothing", async () => {
    const tenant = await createTenant("scratchclone5", "free");
    // Bypass the service quota to put 101 live issues (free allows 100) in the source.
    for (let i = 0; i < 101; i += 1) {
      await issueRepo.insertIssue(
        { ...issueInput(tenant.org.id, tenant.project.id, { title: `Bulk ${i}` }) } as never,
        tenant.userIds.member,
        i + 1,
      );
    }
    const before = await projectRepo.listProjects({ orgId: tenant.org.id, limit: 100, cursor: null });
    await expect(projectService.cloneProject(tenant.actors.member, {
      orgId: tenant.org.id, projectId: tenant.project.id, name: "Too Big", slug: "too-big", key: "TB", includeIssues: true,
    })).rejects.toThrow(/allows 100 issues per project; this clone would copy 101/);
    const after = await projectRepo.listProjects({ orgId: tenant.org.id, limit: 100, cursor: null });
    expect(after.total).toBe(before.total);
    // without issues the same project clones fine
    const ok = await projectService.cloneProject(tenant.actors.member, {
      orgId: tenant.org.id, projectId: tenant.project.id, name: "No Issues", slug: "no-issues", key: "NI", includeIssues: false,
    });
    expect(ok.id).toBeTruthy();
    void (null as unknown as OrgId);
  });
});
